'use strict';
const buttons=[...document.querySelectorAll('[data-width]')];
buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('.frame-stage').forEach(stage=>stage.dataset.width=button.dataset.width)}));
const promptToggle=document.querySelector('#toggle-prompts'),prompts=document.querySelector('#prompts');
promptToggle.addEventListener('click',()=>{const opening=prompts.hidden;prompts.hidden=!opening;promptToggle.setAttribute('aria-expanded',String(opening));promptToggle.textContent=opening?'Hide prompts':'Show prompts'});
document.querySelector('#b-prompt').textContent="Act as a professional portfolio designer and web\ndeveloper. Help me build a modern, interactive\nportfolio that I can share with companies and\nrecruiters to showcase my skills, projects,\neducation, interests, and career goals. Start by\nasking me questions about my background,\ntechnical skills, achievements, projects, and the\nroles I want to pursue. Use my answers to create\na portfolio that reflects my personality while\npresenting me professionally. Organize the\ncontent into clear sections and highlight my\nstrongest projects with their goals, my\ncontributions, technologies used, and results\nwhere available. Create a unique visual identity\nwith clean layouts, readable typography, smooth\nanimations, and responsive design across\nmobile, tablet, and desktop. Make the portfolio\neasy to navigate and include working links and a\nclear way for recruiters to explore my work and\ncontact me through a method I approve. Do not\ninvent achievements, skills, experience, or\nresults. Include only information I approve for\npublic sharing and never expose sensitive\npersonal details, credentials, or confidential\ninformation. Build a functional MVP rather than\na static mockup. Before presenting the final\nversion, test the main interactions, navigation,\nresponsiveness, and content accuracy, fix any\nissues you find, and summarize what is ready to\nshare and what still needs attention.";
